function setLang(l){
  localStorage.setItem('ptaLang',l);
  document.documentElement.lang=l;
  document.body.classList.toggle('en-mode',l==='en');
  document.querySelectorAll('[data-i18n]').forEach(e=>{
    const k=e.getAttribute('data-i18n');
    if(T[l][k])e.textContent=T[l][k];
  });
  document.getElementById('btn-es').classList.toggle('active',l==='es');
  document.getElementById('btn-en').classList.toggle('active',l==='en');
}
const sl=localStorage.getItem('ptaLang')||'es';
if(sl!=='es')setLang(sl);

/* scroll shadow */
const hdr=document.getElementById('site-header');
window.addEventListener('scroll',()=>{hdr.classList.toggle('scrolled',window.scrollY>10);},{passive:true});

/* burger */
const brg=document.getElementById('burger'),mm=document.getElementById('mobile-menu');
brg.addEventListener('click',()=>{const o=brg.classList.toggle('open');brg.setAttribute('aria-expanded',o);mm.classList.toggle('open',o);});
mm.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{brg.classList.remove('open');mm.classList.remove('open');brg.setAttribute('aria-expanded','false');}));

/* scroll reveal escalonado */
const ro=new IntersectionObserver((es)=>{
  es.forEach((e,i)=>{
    if(e.isIntersecting){setTimeout(()=>e.target.classList.add('visible'),i*90);ro.unobserve(e.target);}
  });
},{threshold:0.12});
document.querySelectorAll('.reveal').forEach(e=>ro.observe(e));

/* counters animados */
const co=new IntersectionObserver((es)=>{
  es.forEach(e=>{
    if(!e.isIntersecting)return;
    co.unobserve(e.target);
    const el=e.target,target=+el.dataset.target,dur=1400,t0=performance.now();
    function tick(t){
      const p=Math.min((t-t0)/dur,1);
      el.textContent=Math.round(target*(1-Math.pow(1-p,3)));
      if(p<1)requestAnimationFrame(tick);
    }
    requestAnimationFrame(tick);
  });
},{threshold:0.4});
document.querySelectorAll('.counter').forEach(el=>co.observe(el));

/* acordeones FAQ */
function toggleFaq(btn){
  const item=btn.closest('.faq-item'),body=item.querySelector('.faq-a'),open=item.classList.contains('open');
  document.querySelectorAll('.faq-item.open').forEach(o=>{
    o.classList.remove('open');
    o.querySelector('.faq-a').style.maxHeight='0';
    o.querySelector('.faq-q').setAttribute('aria-expanded','false');
  });
  if(!open){
    item.classList.add('open');
    body.style.maxHeight=body.scrollHeight+'px';
    btn.setAttribute('aria-expanded','true');
  }
}

/* footer contact gate */
function revealFooterContact(e){
  e.preventDefault();
